/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

extern M2C_UNK gSaveRawSlots;

/* Returns the 16-bit field at bits 8-23 of the first word of a 32-byte save slot; 0 if the slot index is out of range (>= 16). */ s32 getSaveSlotValue(s32 slotIndex) {
    u32 slot;

    slot = slotIndex & 0xFFFF;
    if (slot >= 0x10U) {
        return 0;
    }
    return ((u32) *((M2C_UNK *)((s8 *)&gSaveRawSlots + (slot << 5))) >> 8) & 0xFFFF;
}
